head.script:
scwin.init = function() {
    var json = [{
            "col1": "",
            "aplcBegYmd": "",
            "aplcEndYmd": "",
            "stdDpsAmt": "",
            "lbAplyBegYmd": "",
            "lbAplyEndYmd": "",
            "apdtStdDedeDay": "",
            "redtStdDedeDay": "",
            "adchRate": "",
            "aplcYnCd": "",
            "ctnrCd": "",
            "ctnrCdNm": "",
            "useYnCd": "",
            "regSqno": "",
        },
        {
            "col1": "",
            "aplcBegYmd": "",
            "aplcEndYmd": "",
            "stdDpsAmt": "",
            "lbAplyBegYmd": "",
            "lbAplyEndYmd": "",
            "apdtStdDedeDay": "",
            "redtStdDedeDay": "",
            "adchRate": "",
            "aplcYnCd": "",
            "ctnrCd": "",
            "ctnrCdNm": "",
            "useYnCd": "",
            "regSqno": "",
        }
    ];
    dlt_out.setJSON(json);
    //scwin.scope = this;
    /*
    //팝업 파라미터 받기
    scwin.param =JSON.parse($p.getPopupParam());
    var dataList = "";
    if(scwin.param.length = 1) {
    	//dma_in.set("ctnrCd", scwin.param[0].ctnrCd);	
    	dma_in.setJSON(scwin.param[0]);
    } 
    	// 기준용기금액 보증금 서비스콜
    	pms.serviceCall.tranService(sbm_ctnrDpsList);*/
};
scwin.onpageunload = function() {};
scwin.btn_ins_onclick = function(e) {
    debugger;
    /*
    var chkInx = gridList.getCheckedIndex("col1")[0];
    var row = dlt_out.getRowStatus(chkInx);
    if(row == "C" && dlt_out.getCellData(4, "aplcBegYmd") ) {
    	dlt_out.removeRow(chkInx);
    }
    */
    // 임시 섹션 로그인 사용자정보
    //dma_in.set("loginId", "webmaster");
    dlt_out.setCellData(0, "regSqno", dma_in.get("regSqno"));
    //유효성검사
    scwin.fn_validation();
    if (scwin.resultYn = true) {
        pms.serviceCall.tranService(sbm_saveList);
    }
};
scwin.fn_validation = function() {
    debugger;
    //보증금 적용시작일 체크
    if (com.util.isEmpty(dma_in.get("aplcBegYmd"))) {
        pms.utils.alert("적용시작일이 미입력된 행을 확인하시고 입력하세요.");
        scwin.resultYn = false;
    }
}
scwin.sbm_saveList_submitdone = function(e) {};
scwin.sbm_ctnrDpsList_submitdone = function(e) {
    debugger;
    //행 건수
    var row = dlt_out.getTotalRow();
    //열 건수
    var col = gridList.getTotalCol();
    //오늘 날짜
    var sysDate = pms.utils.getDate();
    for (var i = 0; i < row; i++) {
        if (dlt_out.getCellData(i, "aplcEndYmd") < sysDate) {
            for (var j = 0; j < col; j++) {
                gridList.setRowReadOnly(i, true);
                gridList.setCellClass(i, j, "readonly");
            }
        }
    }
};
scwin.btn_addRow_onclick = function(e) {
    var focusRow = gridList.getFocusedRowIndex() + 1;
    dlt_out.insertRow(focusRow);
    dlt_out.setCellData(focusRow, "ctnrCd", dma_in.get("ctnrCd"));
    dlt_out.setCellData(focusRow, "regSqno", dma_in.get("regSqno"));
};
scwin.btn_removeRow_onclick = function(e) {
    debugger;
    var chkInx = gridList.getCheckedIndex("col1")[0];
    var row = dlt_out.getRowStatus(chkInx);
    if (row == "U") {} else if (row == "C") {
        dlt_out.removeRow(chkInx);
    }
};
scwin.gridList_onviewchange = function(info) {
    debugger;
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#G_'+$p.id+'gridList__aplcEndYmd_input').val() == ''
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "mf_gridList.disableBeforeDate(2, '20251220')");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridList_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridList__aplcEndYmd_img').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridList__aplcEndYmd_img').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridList__aplcEndYmd_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridList__aplcEndYmd_calendar_cell_2_3').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
	scwin.init()
    scwin.resultTot = false;
    scwin.resultYn = false;
    scwin.scope = null;
}
